local function _b64(s)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	s = string.gsub(s, "[^"..b.."=]", "")
	return (s:gsub(".", function(x)
		if x == "=" then return "" end
		local r, f = "", (b:find(x) - 1)
		for i = 6, 1, -1 do r = r .. (f % 2^i - f % 2^(i-1) > 0 and "1" or "0") end
		return r
	end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
		if #x ~= 8 then return "" end
		local c = 0
		for i = 1, 8 do c = c + (x:sub(i, i) == "1" and 2^(8 - i) or 0) end
		return string.char(c)
	end))
end
local function _xor(data, key)
	local out = {}
	local kl = #key
	for i = 1, #data do
		out[i] = string.char(bit32.bxor(string.byte(data, i), string.byte(key, ((i - 1) % kl) + 1)))
	end
	return table.concat(out)
end
local payload = table.concat(_PARTS)
local decoded = _b64(payload)
local key = _b64(_KEY)
local src = _xor(decoded, key)
local fn, err = loadstring(src)
if not fn then
	warn("[NIGHTDLC] decrypt/load failed:", err)
	return
end
fn()
